import heapq

def max_sum_after_operations(n, k, arrays):
    arr_sizes = []
    for i in range(n):
        arr_sizes.append(arrays[i][0])
        for j in range(1, arrays[i][len(arrays[i]) - 1]):
            heapq.heappush(arr_sizes[-1], -1 * arrays[i][arr_sizes[-1].index(j + 1)])
    picked_elements = []
    for _ in range(k):
        largest_element = -1 * heapq.heappop(arr_sizes[-1])
        picked_elements.append(largest_element)
        in_sizes = []
        for elem in arr_sizes[-1]:
            if elem * -1 > largest_element * -1:
                in_sizes.append(largest_element + elem * -1)
        while in_sizes:
            if not arr_sizes or in_sizes[-1] > arr_sizes[-1][-1]:
                heapq.heappush(arr_sizes[-1], -1 * in_sizes[-1])
                in_sizes.pop()
            else:
                break
    return sum(picked_elements)

