    def check_conditions(pairs_list):
        opposite_points = {}
        length = len(pairs_list)
        for i in range(length):
            ptr = (1 + i) % length
            tmp = pairs_list[ptr]
            opp = pairs_list[i]
            if tmp not in opposite_points:
                opposite_points[tmp] = [opp]
            else:
                opposite_points[tmp].append(opp)
            if opp not in opposite_points:
                opposite_points[opp] = [tmp]
            else:
                opposite_points[opp].append(tmp)

            if len(opposite_points[tmp]) == 2:
                same_point_index = (opposite_points[tmp][0] - tmp) % length == 1
                diff_process_len = abs(tmp - opposite_points[tmp][0]) == length - 2
                if not same_point_index and not diff_process_len:
                    potential_seen_first = (ptr > i) or (ptr > i and pairs_list[(ptr - 1) % length]) != tmp
                    if potential_seen_first and pairs_list[ptr] == "?":
                        return False
        inv_pairs = {opposite_points[tmp][0]: tmp for tmp in opposite_points}
        for opp_list in opposite_points.values():
            for orig in opp_list:
                other_or = inv_pairs[orig]
                if other_or == orig:
                    if diff_process_len:
                        continue
                    return False
                if orig in opposite_points and (i - perm.index(inv_pairs[orig]) + i) % length == 1:
                    return False
        return True

    valid_count = 0
    for perm in permutations(points):
        pairs_list = [points[i - 1] for i in range(1, len(points) + 1)]
        if ''.join(perm) == points and check_conditions(pairs_list):
            valid_count += 1
    return valid_count % (10**9 + 7)

