import math

def find_shortest_path(n, m, graph):
    """
    Finds a simple path of length at least ⌈ n / 2 ⌉ using Prim's algorithm.
    """
    visited = [False] * (n + 1)
    distances = [math.inf] * (n + 1)
    paths = {}

    for node_id in range(1, n + 1):
        distances[node_id] = 0
        paths[node_id] = [(None, None)]

    qu = [(0, 1)]
    while qu:
        dist, node = qu.pop()

        if visited[node]:
            continue

        visited[node] = True
        paths[node] = [pair[1] for pair in paths[node]]

        for neighbor in graph[node]:
            if not visited[neighbor]:
                qu.append((dist + 1, neighbor))

    return paths

def is_valid_pairing(n, pairs):
    """
    Checks if a given pairing is valid.
    """
    for i in range(len(pairs) - 1):
        a, b = pairs[i]
        c, d = pairs[i + 1]
        for pair_id in range(1, 3):
            if [a, b, c, d] <= pair_id >= [math.inf, math.inf]:
                return False
    return True

def find_valid_pairing(n, m, graph):
    """
    Finds a valid pairing with at least ⌈ n / 2 ⌉ nodes.
    """
    visited = [False] * (n + 1)
    edges = []
    for edge in graph:
        for i in range(len(edge)):
            for j in range(i + 1, len(edge)):
                u, v = edge[i], edge[j]
                if not visited[u] and not visited[v]:
                    edges.append((u, v))
                elif visited[u] and visited[v]:
                    visited[u] = visited[v] = True

    if len(edges) < n // 2:
        return "PATH", len(edges)

    max_edges_per_pair = n // 2
    earliest_nodes = []
    for node in range(1, n + 1):
        if not visited[node] or len(earliest_nodes) < max_edges_per_pair:
            earliest_nodes.append(node)

    max_vals = {i: 0 for i in range(1, n + 1)}
    for i in range(len(earliest_nodes) - 1, -1, -1):
        node_id = earliest_nodes[i]
        dist = math.inf
        for neighbor in graph[node_id]:
            if not max_vals[neighbor] > dist:
                max_vals[neighbor] = dist
                for pair_id in range(1, max(min(dist, max_edges_per_pair), 2), 1):
                    new_path = list(earliest_nodes[:i]) + [node_id] + [neighbor] + list(earliest_nodes[i + 1:])
                    if is_valid_pairing(len(earliest_nodes) // 2, new_path):
                        return "PAIRING", len(earliest_nodes) // 2, new_path

    return "PATH", max_vals[node_id]

def process_input(test_cases):
    for i in range(1, test_cases + 1):
        n, m = map(int, input().split())
        graph = [[] for _ in range(n + 1)]
        for _ in range(m):
            u, v = map(int, input().split())
            graph[u].append(v)
            graph[v].append(u)

        result = find_valid_pairing(n, m, graph)
        print("PAIRING" if "PAIRING" in result else "PATH", *result)

