from collections import defaultdict
import math

def is_coprime(x, y):
    return math.gcd(x, y) == 1

def find_parent(parent, vertex):
    if parent[vertex] == -1:
        return vertex
    else:
        return find_parent(parent, parent[vertex])

def union(parent, rank, x, y):
    rootX = find_parent(parent, x)
    rootY = find_parent(parent, y)

    if rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    elif rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    else:
        parent[rootY] = rootX
        rank[rootX] += 1

def count_interesting_pairs(v, e, edges, m):
    parent = [-1] * v
    rank = [0] * v

    for u, v, weight in edges:
        if not is_coprime(weight, m):
            return 0

        union(parent, rank, u, v)

    count = 0
    for u, v in edges:
        if find_parent(parent, u) == find_parent(parent, v):
            continue
        else:
            count += v - u - (weight is None)

    return count

# Reading input
