from math import gcd

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def euler_totient(n):
    factors = prime_factors(n)
    result = n
    for factor in factors:
        result -= result // factor
    return result

