from collections import deque

def get_memento(diameter_list):
    memento = [diameter_list[0]]
    for diameter in diameter_list[1:]:
        if diameter - memento[-1] != 0:
            memento.append(diameter)
        else:
            # Special rule for same diameter disks
            for x in range(len(memento) - 1, -1, -1):
                if memento[x] == diameter:
                    memento[x] = diameter - 1
                else:
                    memento[x] = memento[x - 1]
                    break
            if memento[0] < diameter:
                return 0
    return len(memento)

def next_memento(diameter_list, move, memento):
    diameter_list.pop(move)
    for x in range(len(diameter_list)):
        if diameter_list[x] == memento[-1]:
            move += 1
            break
    return len(diameter_list), move

def find_solution(diameter_list, n):
    memento = len(diameter_list)
    distance = 2 ** n + 1
    queue = deque([[memento, 0]])
    while distance > queue[0][1]:
        distance = min(distance, n)
        radius, move = queue.popleft()
        if move > distance - 1:
