        self.graph = [[0] * vertices for _ in range(vertices)]

    def is_valid_path(self, nodes):
        path = set(nodes)
        for i in range(len(nodes) - 1):
            if not self.has_edge(nodes[i], nodes[i + 1]):
                return False
        return True

