import sys
import math

def is_scalable(a, b, cutoff):
    """
    Check if rectangle with size a x b is cuttable by a rectangle with size dx x dy within minimum cost.
    """
    if abs(b - a) <= cutoff:
        return (abs(b - a) <= cutoff) and (a == b) and (max(a, b) <= cutoff)
    vertical_options = math.gcd(a, cutoff) > 0 and math.gcd(b, cutoff) > 0
    horizontal_options = a > 0 and b > 0
    return cutoff <= abs(b - a) and (vertical_options and horizontal_options)

def count_subsets(map, limit):
    """
    Count the number of subsets of the map that sum up to X.
    """
    def memoized_f(depth, total_sum, level_max):
        if total_sum == 1:
            return sum(map[level_max])
        result = 0
        size_pow = (1 << level_max) - 1
        total_sum -= map[level_max][size_pow]
        if total_sum < 0:
            total_sum = 0
        prefix_sum = total_sum
        for max_black in range(size_pow-1, -1, -1):
            if prefix_sum + map[level_max][max_black] <= limit:
                result += memoized_f(depth + 1, total_sum + map[level_max][max_black + size_pow], max(-1, max_black - math.gcd(level_max, max_black + size_pow)))
            prefix_sum += map[level_max][max_black]
        return result
    return memoized_f(0, 0, limit)

