from collections import defaultdict

def find_distance(n, m, edges):
    distance = [[1000000 for _ in range(n)] for _ in range(10)]

    for u, v, w in edges:
        distance[w][u] = distance[w][v] = distance[v][u] = distance[v][w] = w

    for i in range(1, 10):
        queue = [0]
        visited = [False] * n
        distance[i][0] = 0
        kth_distance = 0

        while queue:
            u = queue.pop()
            if visited[u]:
                continue

            visited[u] = True
            kth_distance += 1

            for v in range(1, 10):
                if distance[i][u] == distance[v][1] or distance[i][v] == distance[1][u]:
                    distance[i][v] = min(distance[i][u] + distance[v][1], distance[i][v])
                    if visited[v] and distance[i][v] >= distance[i][u]:
                        queue.append(v)

    permutation_count = 0
    for i in range(1, 10):
        permutation_count += sum(distance[i])

    counter = [defaultdict(int) for _ in range(10)]

    for i in range(19):
        for j in range(10):
            if j != i:
                kth_distance = distance[9][j]
                permutation_count -= counter[j][kth_distance] * (9 - counter[j][kth_distance])
                count = counter[j - 1][kth_distance + 1] + counter[10][kth_distance + 1]
                permutation_count += count * 9
                counter[j % 9][kth_distance + 1] = counter[j - 1][count + kth_distance + 1]

    for i in range(9):
        for j in range(10):
            counter[i][j] = counter[1][j // i]

    mod_inverse = pow(counter[0][1], len(n - 2), (m - 1))

    return permutation_count * mod_inverse * 9 % (m - 1)


