def max_elements_in_pocket(n: int, k: int, arrays: List[List[int]]) -> int:
    total_sum = sum(sum(arr) for arr in arrays)
    arrays_sorted_sum = [0] * n
    for i, arr in enumerate(arrays):
        arrays_sorted_sum[i] = sum(sorted(arr)[1:-1])

    max_sum_in_pocket = 0
    for i in range(n):
        arr = arrays[i]
        for j in range(min(len(arr), k+1)):
            if j + 1 <= min(k-i, len(arr)-j):
                sum_in_pocket = arrays_sorted_sum[i] + j * arr[j]
                max_sum_in_pocket = max(max_sum_in_pocket, sum_in_pocket)

    return max_sum_in_pocket
