    left, right = query[1], query[2]  # query[0] is an arbitrary zero for this operation
    result = query[0]
    if query[0] == 0:
        left, right = query[1], query[2]
        # Remove numbers not within the range L, R
        indices = [i for i in range(len(nums)) if i >= left and i <= right]
        nums = nums[:left] + nums[right+1:]
        for index in indices:
            for x in range(left, right+1):
                number = nums[index]
                # Apply bitwise AND assignment
                nums[index] = number & x
        result = min(nums)
        return result
    else:
