from collections import defaultdict

def assign_ranks(n, m, k, r, orders):
    ranks = [0] * (n + 1)  # Initialize ranks with zeros

    # Create an adjacency list for orders
    order_adjacencies = defaultdict(list)
    for x, y in orders:
        order_adjacencies[x].append(y)

    # Assign ranks from left to right
    used_ranks = set()
    curr_rank = 1

    for i in range(1, n + 1):
        if ranks[i] == 0 and i not in used_ranks:
            if curr_rank in used_ranks:
                curr_rank += 1
            ranks[i] = curr_rank
            used_ranks.add(curr_rank)
        if ranks[i] != 0:
            curr_rank = ranks[i]

        # Attempt to assign new ranks to dependencies
        for next_rank in range(1, k + 1):
            if next_rank > curr_rank:
                break
            if (next_rank not in ranks) or sums := set(order_adjacencies[next_rank]) - {next_rank}:
                for y in sums:
                    if y not in used_ranks:
                        ranks[y] = next_rank
                        used_ranks.add(next_rank)
                        break

                for y in sums:
                    if y not in used_ranks:
                        break
    used_latest_rank = next_rank if next_rank > 0 else 0

    if 0 in ranks or max(ranks) != k or any(ranks[i] != ranks[ranks.index(i)] for i in r if ranks[i] != r[i]):
        return -1
    return ranks[:n]

