def find_divisors(n):
    divisors = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add((i, n // i))
    return divisors

def cut_rectangles(A, B):
    return (A + 1) * (B + 1)

def compute_sum_of_products(divisors):
    product_sum = 0
    product = 1
    for div1, div2 in divisors:
        product_sum += product
        product *= div1 * div2
    return product_sum

