def max_row_sum(matrix):
    n, m = len(matrix), len(matrix[0])
    # Calculate prefix maxima for each column in each row
    for i in range(n):
        max_vals = [-1] * m
        for j in range(m):
            if max_vals[j] == -1 or max_vals[j] <= matrix[i][j]:
                max_vals[j] = matrix[i][j]
        for j in range(m):
            matrix[i][j] = max_vals[j]

    # Sum the max values for each row
    return sum(row[i] for row in matrix for i in range(m))

