def min_trees_to_feed(n, k, l, r):
    friends = [set() for _ in range(n+1)]
    for u, v in zip(range(1, n+1), range(k+1, n+1)):
        friends[u].add(v)
        friends[v].add(u)

    def dfs(friend):
        unique = set([friend])
        queue = [friend]
        while queue:
            parent = queue.pop()
            for child in friends[parent]:
                if child not in unique:
                    unique.add(child)
                    queue.append(child)
        return len(unique)

