    trees = [set() for _ in range(n)]
    for u, v in lineinfile():
        i = get_index(u, k)
        j = get_index(v, k)
        i -= adjacent(i, n, k)
        j -= adjacent(j, n, k)

        if i < j:
            trees[i].update([v])
            trees[j].add(v)
        else:
            trees[j].update([i])
            trees[i].add(i)

    for _ in range(q):
        l, r in lineinfile():
            l -= adjacent(l, n, k)
            r -= adjacent(r, n, k)
            result = 0 if len(trees[l]) > 0 else 1
            result += len(trees[r + 1:])
