def get_index(x, k):
    return fence_x(x - 1, k)

def adjacent(x, n, k):
    return fence_x(x - 1, k) - x - 1

def fence_x(x, k):
    return n - log2_floor(n - x + k)

def log2_floor(num):
    bits = 0
    while num > 1:
        num >>= 1
        bits += 1
    return bits

