import sys

def find_minimum_trees(n, k, trees, m, pairs, queries):
    """
    Finds the minimum number of trees for feeding to ensure all fed families get information.
    :param n: int, number of trees
    :param k: int, maximum distance between friend families
    :param trees: list, trees with friends
    :param m: int, number of friend family pairs
    :param pairs: list of tuples, friend family pairs
    :param queries: list of int, queries with ranges
    :return: list of int, results for each query
    """
    # Calculate the update and query intervals
    update_interval = 5 * k + 1
    query_interval = k * 2 + 1
    nums = [i for i in range(n)]

    for pair in pairs:
        u, v = pair
        if v < u:
            v, u = u, v

        left_index = (u - 1) // update_interval
        right_index = (v - 1) // update_interval

        if u > n // update_interval + 1 and left_index == 0:
            nums[u - 1] = u
            continue

        if v < k * (n // query_interval) and right_index == query_interval - 1:
            nums[v] = v
            continue

        change = query_interval - left_index if v < k * (n // update_interval) else k * (n // query_interval) - v - 1
        nums[u - 1 + change] = v
        if u < v:
            nums[v] = u

    # BFS to find connected components
    queue = {}
    for i in range(1, n + 1):
        if nums[i] == i:
            queue[nums[i]] = queue.get(nums[i], []) + [dict(i=i, nr=i)]
            queue[nums[i]] = queue[nums[i]].extend([dict(i=i) for i in range(1, k + 1)])
    steps = 0

    def bfs(start):
        if start not in queue or steps > n:
            return 0
        queue[start][0]['nr'] = start
        queue[start][0]['cycle'] = steps
        stack = [start]
        for cur in stack:
            diff = {}
            for neighbor in queue[cur]:
                if neighbor.nl != cur:
                    diff[neighbor.nr] = neighbor.nl
            if len(diff) == k - 1:
                return steps + 1
            queue[cur][0].update(diff)
            for neighbor in queue[cur]:
                if neighbor.nl != cur:
                    stack.append(neighbor)
                    if len(stack) > n:
                        step = steps - stack.pop(0)[0] + len(queue[neighbor.nl]) + 1
                        return (steps + 1) if neighbor.nr in queue and steps + 1 > len(queue[neighbor.nr]) + 1 else step
                else:
                    steps += 1

    for l, r in queries:
        cycle = 1
        for i in range(l - 1):
            if bfs(nums[i]):
                cycle += 1
        print(cycle)  
